                            as i64
                    })
                    .cloned(),
                None => rows.first().cloned(),
            };
            if let Some(nearest) = nearest {
                self.board_scroll.scroll_to_item(at as usize);
                self.focus_row(&nearest, window, cx);
            }
            return;
        }
    }

