/// How a sent story's task stands.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum StoryState {
    Queued,
    Running,
    Paused,
    Done,
    Failed,
    Cancelled,
    /// Its task can't be found: its record deleted, never recorded, or lost
