            assert_eq!((composer.section, composer.at), (Section::Backlog, 2));
            assert!(composer.title.read(cx).focus_handle(cx).is_focused(window));
            window.find("planning-composer-backlog");
        })
        .unwrap();

        type_title("Three", cx);
